head.script:
scwin.trigger1_onclick = function(e) {
    fusionchart1.exportJSChart("jpg");
};
scwin.trigger2_onclick = function(e) {
    //alert(fusionchart1.getActionURI());
    localStorage.setItem("log", fusionchart1.getActionURI());
};
scwin.trigger3_onclick = function(e) {
    //alert(fusionchart1.setActionURI("test"));
    log1 = fusionchart1.setActionURI("test");
    localStorage.setItem("log1", fusionchart1.setActionURI("test"));
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 get버튼을 실행한다.
    //1. Execute the get button after executing the sample file.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'engine/servlet/customexportFusionChart.jsp'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 get버튼을 실행한다.
    //1. Execute the get button after executing the sample file.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    // verify step 1. 알림창에 'engine/servlet/customexportFusionChart.jsp'값이 보여진다.
    //1. The 'engine / servlet / customexportFusionChart.jsp' value is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 'true'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. 다시 get버튼을 실행한다.
    //3. Execute the get button again.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    // verify step 3. 알림창에 'test'값이 보여진다.
    //3. The 'test' value is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.toptions = {
        "startValue": "10000",
        "color": "FF0030",
        "displayValue": "TrendLine"
    };
    //fusionchart1.addTrendLine(toptions);
    window.options = {
        "caption": "Monthly revenue for last year",
        "subCaption": "Harry's SuperMart",
        "xAxisName": "Month",
        "yAxisName": "Revenues (In USD)",
        "placevaluesInside": "1",
        "numberPrefix": "$",
        "showXAxisLine": "10",
        "theme": "fint",
        "rotatevalues": "30",
        "showValues": "true",
        "numDivLines": "5",
        "labelFontSize": "30"
    };
    fusionchart1.setChartAttribute(options);
    fusionchart1.draw();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 25-Jan-2018
    window.isShow = (fusionchart1.getActionURI() == "engine/servlet/customexportFusionChart.jsp");
    localStorage.removeItem("log");
    localStorage.removeItem("log1");
    //end unitTest
}
